import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Debugging","description":"","frontmatter":{},"headers":[],"relativePath":"dev/debugging.md","filePath":"dev/debugging.md"}'),i={name:"dev/debugging.md"};function n(r,e,l,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h1><h2 id="read-the-boot-log-first" tabindex="-1">Read the boot log first <a class="header-anchor" href="#read-the-boot-log-first" aria-label="Permalink to &quot;Read the boot log first&quot;">​</a></h2><p>Every subsystem prints one <code>.... OK</code> line at bring-up. The last line that did NOT print is your failing subsystem. Capture it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none</span></span></code></pre></div><h2 id="in-guest-tools" tabindex="-1">In-guest tools <a class="header-anchor" href="#in-guest-tools" aria-label="Permalink to &quot;In-guest tools&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dmesg            (kernel ring buffer)</span></span>
<span class="line"><span>oc&gt; logcat           (live follow of the persistent log)</span></span>
<span class="line"><span>oc&gt; logctl           (log levels + filters)</span></span>
<span class="line"><span>oc&gt; health           (CPU/mem/tasks/IO + alarms)</span></span>
<span class="line"><span>oc&gt; exc              (exception self-test - proves the trap path)</span></span>
<span class="line"><span>oc&gt; crashlog         (past crash records on /etc)</span></span>
<span class="line"><span>oc&gt; dumpinfo         (crash dump details)</span></span></code></pre></div><h2 id="the-panic-path" tabindex="-1">The panic path <a class="header-anchor" href="#the-panic-path" aria-label="Permalink to &quot;The panic path&quot;">​</a></h2><p>A kernel panic dumps the exception frame (registers + fault address) to serial and writes a crashlog to /etc. <code>crashtest</code> triggers a deliberate one - use it to validate that your /etc volume and serial capture are wired correctly before you need them.</p><h2 id="host-side-debugging-of-the-kernel" tabindex="-1">Host-side debugging of the kernel <a class="header-anchor" href="#host-side-debugging-of-the-kernel" aria-label="Permalink to &quot;Host-side debugging of the kernel&quot;">​</a></h2><ul><li>Debug symbols: the pipeline links with <code>-g</code>, then strips the final ELF; <code>build/opencube_base.elf</code> (pre-<code>strip</code>, produced during <code>make kernel</code>) is your symbol carrier.</li><li>In QEMU: <code>-d int,cpu_reset -D qemu.log</code> logs interrupts and resets; <code>-s -S</code> plus gdb (<code>target remote localhost:1234</code>) gives you the classic remote-debug loop.</li><li>The reproducible build means a crash reproduced twice is <em>the same bytes</em> - no heisen-builds across attempts.</li></ul><h2 id="host-unit-tests" tabindex="-1">Host unit tests <a class="header-anchor" href="#host-unit-tests" aria-label="Permalink to &quot;Host unit tests&quot;">​</a></h2><p><code>make test</code> compiles and runs the harnesses under <code>tests/host_*.c</code> against the real kernel sources (crypto vectors, tar, gzip, string, FAT structures, mbi parsing with ASAN on the host compiler). A regression here is much faster to iterate on than a boot loop.</p><h2 id="known-sharp-edges-from-the-audit-trail" tabindex="-1">Known-sharp edges (from the audit trail) <a class="header-anchor" href="#known-sharp-edges-from-the-audit-trail" aria-label="Permalink to &quot;Known-sharp edges (from the audit trail)&quot;">​</a></h2><ul><li>xHCI DMA above 4 GiB is refused at probe and per-transfer - check your QEMU memory size if a xHCI device vanishes.</li><li>ATA-DMA alignment depends on the heap&#39;s 32-byte block header; if you touch <code>mem_heap.c</code>, run <code>fstest</code> + a FAT32 mount test.</li><li>The multiboot2 parser validates tag sizes; a &quot;hand-built&quot; mbi in tests must respect the per-tag minimums or the parse stops early.</li></ul>`,14)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
